//! 🧪️ Independent causes and actual capacity survive allocation refusal.
use super::*;
use crate::ValueRefusalKind;
fn cause(value:&serde_json::Value)->Option<ValueError>{value.as_str().map(|text|ValueError::new(ValueRefusalKind::Canceled,text.to_owned()))}
#[test]
fn allocation_failure_retains_schema_causes_and_physical_progress(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../🛬️decode/🛂️allocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for case in fixture["allocationSettlement"].as_array().unwrap(){let f=&case["failure"];let actual=(case["allocated"].as_u64().unwrap()>0).then(||case["allocated"].as_u64().unwrap()as usize);let result=NativeAllocationFailure{primary:cause(&f["primary"]),admission:cause(&f["admission"]),forwarded_admission:cause(&f["forwardedAdmission"]),scoped_admission:cause(&f["scopedAdmission"]),forwarded_quote:cause(&f["forwardedQuote"]),scoped_quote:cause(&f["scopedQuote"]),forwarded_post:cause(&f["forwardedPost"]),scoped_post:cause(&f["scopedPost"]),forwarded_cancel:cause(&f["forwardedCancel"]),scoped_cancel:cause(&f["scopedCancel"]),receipt:cause(&f["receipt"]),extent:cause(&f["extent"]),progress:NativeAllocationProgress{prior_admitted_bytes:Some(case["prior"].as_u64().unwrap()as usize),requested_bytes:Some(case["requested"].as_u64().unwrap()as usize),maximum_bytes:Some(case["maximum"].as_u64().unwrap()as usize),admitted_bytes:case["admitted"].as_u64().unwrap()as usize,actual_capacity_bytes:actual}};let causes=[&result.primary,&result.admission,&result.forwarded_admission,&result.scoped_admission,&result.forwarded_quote,&result.scoped_quote,&result.forwarded_post,&result.scoped_post,&result.forwarded_cancel,&result.scoped_cancel,&result.receipt,&result.extent];for(key,value)in ["primary","admission","forwardedAdmission","scopedAdmission","forwardedQuote","scopedQuote","forwardedPost","scopedPost","forwardedCancel","scopedCancel","receipt","extent"].into_iter().zip(causes){assert_eq!(value.as_ref().map(|error|error.message.as_ref()),f[key].as_str());}assert_eq!(result.is_empty(),causes.iter().all(|value|value.is_none()));assert_eq!(result.progress.actual_capacity_bytes,actual);}
}
